mapper.select:
select COALESCE(b.device_name,dataTable.device_name) as 'deviceName', count(DISTINCT oa.algorithm_code) as 'algorithmNum', dataTable.device_code as 'deviceCode' from vm_order_devices dataTable inner join vm_order_algorithms oa on dataTable.package_code = oa.package_code and dataTable.order_code = oa.order_code and dataTable.industry_code = oa.industry_code left join (select distinct device_code, device_name,tenant_id,industry_code from vm_tenant_device_channel_rel_t where delete_flag='0') b on b.device_code = dataTable.device_code and b.tenant_id = dataTable.tenant_id and b.industry_code = dataTable.industry_code left join vm_device_info_t t on t.device_code = dataTable.device_code LEFT JOIN vm_algorithm_info_t t2 ON oa.algorithm_code = t2.algorithm_code where dataTable.delete_flag = '0' and dataTable.ord_status IN (0, 1, 2) and t.delete_flag = '0' and app_scenarios = '1'
and dataTable.device_code in
#{item}
and ( t.province_id in
#{item}
or t.city_id in
#{item}
or t.county_id in
#{item}
or t.town_code in
#{item}
)
${dataScope} group by dataTable.device_code order by count(DISTINCT oa.algorithm_code) desc, dataTable.device_code asc

SELECT COALESCE(b.channel_name,c.channel_name) as 'channelName', COUNT(1) AS 'foreAlgorithmTaskNum', od.device_code as 'deviceCode' FROM `vm_algorithm_give_config` ag left join vm_device_info_t t on t.device_code = ag.device_code left JOIN vm_order_devices od ON od.device_code = t.device_code and od.tenant_id = ag.tenant_id AND ag.industry_code = od.industry_code left join vm_channel_info_t c on t.device_code = c.device_code and c.channel_code = ag.channel_code left join vm_tenant_device_channel_rel_t b on b.device_code = od.device_code AND b.channel_code = c.channel_code AND b.industry_code = od.industry_code AND b.tenant_id = od.tenant_id AND b.delete_flag='0' where ag.delete_flag = '0' and od.delete_flag = '0' and od.ord_status IN (0, 1, 2) and t.delete_flag = '0' and c.delete_flag = '0'
and ag.device_code in
#{item}
and ( t.province_id in
#{item}
or t.city_id in
#{item}
or t.county_id in
#{item}
or t.town_code in
#{item}
)
${dataScope} GROUP BY ag.channel_code order by count(1) desc, ag.channel_code asc

mapper.sql:
left join vm_device_info_t t on t.device_code = ac.device_code
left JOIN vm_order_devices od ON od.device_code = t.device_code and od.tenant_id = ac.tenant_id AND ac.industry_code = od.industry_code
left join vm_channel_info_t c on t.device_code = c.device_code and c.channel_code = ac.channel_code
left join vm_tenant_device_channel_rel_t b on b.device_code = od.device_code AND b.channel_code = c.channel_code AND b.industry_code = od.industry_code
                                            AND b.delete_flag='0' AND b.tenant_id = od.tenant_id
where ac.delete_flag = '0' and od.delete_flag = '0' and od.ord_status IN (0, 1, 2) and t.delete_flag = '0' and c.delete_flag = '0'


        and ac.device_code in

            #{item}




    and (
    t.province_id in

        #{item}

    or
    t.city_id in

        #{item}

    or
    t.county_id in

        #{item}

    or
    t.town_code in

        #{item}

    )

${dataScope}
GROUP BY ac.channel_code order by count(1) desc, ac.channel_code asc

mapper.select:
SELECT COALESCE(b.channel_name,c.channel_name) as 'channelName', COUNT(IF(ag.`status` = '0', 1, NULL)) AS 'startForeAlgorithmTaskNum', od.device_code as 'deviceCode' FROM `vm_algorithm_give_config` ag left join vm_device_info_t t on t.device_code = ag.device_code left JOIN vm_order_devices od ON od.device_code = t.device_code and od.tenant_id = ag.tenant_id AND ag.industry_code = od.industry_code left join vm_channel_info_t c on t.device_code = c.device_code and c.channel_code = ag.channel_code left join vm_tenant_device_channel_rel_t b on b.device_code = od.device_code AND b.channel_code = c.channel_code AND b.industry_code = od.industry_code AND b.tenant_id = od.tenant_id AND b.delete_flag='0' where ag.delete_flag = '0' and od.delete_flag = '0' and od.ord_status IN (0, 1, 2) and t.delete_flag = '0' and c.delete_flag = '0'
and ag.device_code in
#{item}
and ( t.province_id in
#{item}
or t.city_id in
#{item}
or t.county_id in
#{item}
or t.town_code in
#{item}
)
${dataScope} GROUP BY ag.channel_code
HAVING startForeAlgorithmTaskNum>0
order by COUNT(IF(ag.`status` = '0', 1, NULL)) desc, ag.channel_code asc

