mapper.select:
SELECT DISTINCT dt.device_code
from sys_dept d LEFT JOIN vm_organ_device_rel_t dt ON d.DEPT_ID = dt.dept_id
left join vm_order_devices od on dt.device_code = od.device_code
WHERE od.delete_flag = '0' and od.ord_status IN (0, 1, 2) and dt.device_type NOT IN (8,9,10) AND od.tenant_id=#{tenantId} and od.industry_code=#{industryCode}

    and d.DEPT_ID in

